// Writes src/version.ts from package.json: the one place the version is kept. Run by `build` and `test`; the
// generated file is not committed.
import { readFileSync, writeFileSync } from "node:fs";

const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
writeFileSync(
  new URL("../src/version.ts", import.meta.url),
  `// Generated by scripts/version.mjs from package.json. Do not edit.\nexport const VERSION = ${JSON.stringify(pkg.version)};\n`,
);
